% openmp_analysis.m
% Analyze results generated by openmp_unblocked_benchmark.sh
% Requires MATLAB

clear; clc; close all;

scriptDir = fileparts(mfilename('fullpath'));
csvFile = fullfile(scriptDir, 'openmp_unblocked_results.csv');
if ~isfile(csvFile)
    error('Missing %s. Run the benchmark script on Zeus first.', csvFile);
end

data = readtable(csvFile);
required = {'trial', 'threads', 'execution_time_seconds'};
if ~all(ismember(required, data.Properties.VariableNames))
    error('CSV must contain: trial, threads, execution_time_seconds.');
end
if isempty(data) || any(~isfinite(data.execution_time_seconds)) ...
        || any(data.execution_time_seconds <= 0)
    error('CSV is empty or contains invalid execution times.');
end

threads = unique(data.threads)';
n = numel(threads);
counts = zeros(n, 1);
meanTime = zeros(n, 1);
stdTime = zeros(n, 1);
medianTime = zeros(n, 1);
ci95 = zeros(n, 1);

for k = 1:n
    subset = data(data.threads == threads(k), :);
    times = subset.execution_time_seconds;
    counts(k) = numel(times);

    if counts(k) < 2
        error('Need at least 2 measurements for %d threads.', threads(k));
    end
    if numel(unique(subset.trial)) ~= counts(k)
        error('Duplicate trial IDs detected for %d threads.', threads(k));
    end

    meanTime(k) = mean(times);
    stdTime(k) = std(times); % Sample standard deviation (N-1)
    medianTime(k) = median(times);

    % Exact two-sided 95%% t confidence interval, using base MATLAB.
    df = counts(k) - 1;
    betaPoint = betaincinv(0.05, df/2, 0.5);
    tCritical = sqrt(df * (1/betaPoint - 1));
    ci95(k) = tCritical * stdTime(k) / sqrt(counts(k));
end

baselineIndex = find(threads == 1, 1);
if isempty(baselineIndex)
    error('No single-thread baseline found in CSV.');
end

speedup = meanTime(baselineIndex) ./ meanTime;
efficiency = 100 * speedup ./ threads(:);
summary = table(threads(:), counts, meanTime, stdTime, medianTime, ...
    ci95, speedup, efficiency, ...
    'VariableNames', {'Threads', 'Trials', 'Mean_s', 'StdDev_s', ...
                      'Median_s', 'CI95_HalfWidth_s', 'Speedup_x', ...
                      'Efficiency_percent'});

fprintf('\nUNBLOCKED OPENMP BENCHMARK SUMMARY\n');
disp(summary);
fprintf('Mean timing confidence intervals are mean +/- CI95_HalfWidth_s.\n');
fprintf('Speedup is calculated from MEAN execution times.\n');

if ismember('node', data.Properties.VariableNames)
    nodes = unique(string(data.node));
    fprintf('Node(s): %s\n', strjoin(cellstr(nodes), ', '));
    if numel(nodes) > 1
        warning('CSV combines data from multiple nodes; comparisons may be unfair.');
    end
end

% Plot 1: average execution times and 95%% confidence intervals.
fig1 = figure('Color','w','Position',[100 100 900 530]);
errorbar(threads, meanTime, ci95, 'o-', 'LineWidth', 1.8, ...
    'MarkerSize', 7, 'CapSize', 12);
grid on;
xticks(threads);
xlabel('Number of OpenMP threads');
ylabel('Execution time (seconds)');
title('Unblocked OpenMP: Mean Execution Time (95% CI)');
ylim([0, max(meanTime + ci95) * 1.15]);
saveas(fig1, fullfile(scriptDir, 'openmp_unblocked_mean_time.png'));

% Plot 2: measured speedup versus ideal linear speedup.
fig2 = figure('Color','w','Position',[140 140 900 530]);
plot(threads, speedup, 'o-', 'LineWidth', 1.8, 'MarkerSize', 7);
hold on;
plot(threads, threads, '--', 'LineWidth', 1.5);
hold off;
grid on;
xticks(threads);
xlabel('Number of OpenMP threads');
ylabel('Speedup compared with 1 thread');
title('Unblocked OpenMP: Average Speedup');
legend('Measured speedup', 'Ideal linear speedup', 'Location', 'northwest');
saveas(fig2, fullfile(scriptDir, 'openmp_unblocked_speedup.png'));

% Exploratory, paired two-sided t-tests: compare neighboring thread counts.
% Measurements in the same trial are paired, since all configurations ran
% in that round. The order within each trial was randomized.
if n > 1
    comparisons = [threads(1:end-1)', threads(2:end)'];
    if n > 2
        comparisons(end+1, :) = [threads(1), threads(end)];
    end

    m = size(comparisons, 1);
    rawP = zeros(m, 1);
    meanDifference = zeros(m, 1);
    pairedCount = zeros(m, 1);

    for k = 1:m
        a = data(data.threads == comparisons(k,1), :);
        b = data(data.threads == comparisons(k,2), :);
        [sharedTrials, ia, ib] = intersect(a.trial, b.trial);
        differences = a.execution_time_seconds(ia) ...
                    - b.execution_time_seconds(ib);

        pairedCount(k) = numel(sharedTrials);
        if pairedCount(k) < 2
            error('Not enough paired trials for comparison %d.', k);
        end
        meanDifference(k) = mean(differences);
        sampleStd = std(differences);

        if sampleStd == 0
            rawP(k) = double(meanDifference(k) == 0);
        else
            df = pairedCount(k) - 1;
            tValue = meanDifference(k) / (sampleStd/sqrt(pairedCount(k)));
            % Two-sided Student t p-value without Statistics Toolbox.
            rawP(k) = betainc(df / (df + tValue^2), df/2, 0.5);
        end
    end

    % Bonferroni correction for this family of multiple comparisons.
    adjustedP = min(1, m * rawP);
    pTable = table(comparisons(:,1), comparisons(:,2), pairedCount, ...
        meanDifference, rawP, adjustedP, ...
        'VariableNames', {'Threads_A', 'Threads_B', 'PairedTrials', ...
                          'MeanTime_A_minus_B_s', 'P_raw', 'P_Bonferroni'});
    fprintf('\nEXPLORATORY PAIRED t-TESTS (two-sided)\n');
    disp(pTable);
    fprintf(['Positive mean difference means B was faster on average.\n' ...
             'P-values assume independent rounds and approximately normal\n' ...
             'paired differences; shared-system load can affect results.\n']);
end

fprintf('\nSaved graphs:\n');
fprintf('  openmp_unblocked_mean_time.png\n');
fprintf('  openmp_unblocked_speedup.png\n');
